Method.Implementation:
set obj = ##class(Ens.StringRequest).%New()
set tStatus=##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup("IHC.ITF.Process.Bpl.Oax.OaxLdapQueryDetails","MaxSeqQuery",.tQuery)
if ($$$ISOK(tStatus)){  
 set obj.StringValue=tQuery
}
if obj.StringValue=""{
    Set errorMessage = "MaxSeqQuery:>>" _MaxSeqQuery_"Is not Configured in IHC.ITF.Process.Bpl.Oax.OaxLdapQueryDetails LookupTable"
  Set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(process.%ConfigName, errorMessage)
 } 
 quit obj

	$$$TRACE("Inside Method Set MaxseqnumP1111")	
	//Get the connection
	if (..connection="") || (..connection.isClosed()) {
	   do ..getConnection()
	   do ..connection.setAutoCommit(1)
	}
	$$$TRACE("After Connection11")
	//Create Statement
	set query=pRequest.StringValue
	set ..seqStatement = ..connection.prepareStatement(query)
	$$$TRACE("After Statememt")
	// Execute mspr query
    set tResultSet = ..seqStatement.executeQuery()
    $$$TRACE("After Query Excted")
    while tResultSet.next() 
	{
		 set id = tResultSet.getString(1)
	}
	$$$TRACE("Current Max Id:"_id)
	set id = id+1
	$$$TRACE("Incremented:"_id)
	set pResponse = ##class(Ens.StringResponse).%New()
	set pResponse.StringValue=id
	do pResponse.%Save()
	$$$TRACE("After values")
	//close the connection
	//do ..connection.close()
	//Close the gateway
	//do ..gateway.%Disconnect()
	$$$TRACE("After Close")
	quit pResponse

	try{
     set sourceSystem=pRequest.SourceSystem
     $$$TRACE("SOURCE SYS:"_sourceSystem)
     //Get the MaxSeq Query
	Set query = ..getMaxQueryFromLookUpTable()
	Set response = ..getMaxSeqNum(query)
	$$$TRACE("response Max Seq:>>>"_response.StringValue)
	set ..tempId = response.StringValue
	//Get the connection
	if (..connection="") || (..connection.isClosed()) {
	   do ..getConnection()
	   do ..connection.setAutoCommit(1)
	}	//set the commit false
	$$$TRACE("Set AutoCommit true:"_..connection.getAutoCommit())
    //Move the cursor    
    if sourceSystem="OR"{
	  $$$TRACE("HR insert...")
      do ..insertOracleHrToLdapTable(pRequest)
    }elseif (sourceSystem="CO") || (sourceSystem="CA") {
	  $$$TRACE("CA or CO insert...")	
      do ..insertCactusOrCorpprvToLdapTable(pRequest)
    }
    $$$TRACE("Insert is done ...")	
    //do ..connection.close()
    //Close the gateway
	//  do ..gateway.%Disconnect()
	//  $$$TRACE("Closed gateway connection...")	
	  set tsc =1
	} 
	Catch eException {
		Set tSC = eException.AsStatus()
		$$$LOGSTATUS(tSC)
        Set pResponse=##class(HS.Message.IHE.XDSb.QueryResponse).%New()
		If $isObject($g(tResponse)) {
			Do pResponse.ContentStream.CopyFrom(tResponse.ContentStream)
		}
		Do pResponse.Errors.logError("XDSbConsumer","Error",$system.Status.GetErrorText(tSC))
		$$$TRACE("Inside Catch111")
		do ..connection.rollback()
		do ..connection.close()
	   //Close the gateway
	   do ..gateway.%Disconnect()	   
	   set tsc = $$$ERROR("Error while inserting data to database")	    	  
	}
	quit tsc

	  $$$TRACE("Inside insertOracleHrToLdapTable...")
	  do ..createQueryStatement(pRequest)
      // Execute mspr query
      set ..msprInfoRs = ..msprInfoStmt.executeQuery()
      $$$TRACE("After query Execution1")
      //Execute the Mspr Provider Afflication query
      set ..msprAffRs = ..msprProviderAfflicationStmt.executeQuery()
      $$$TRACE("After query Execution")
	  do ..msprInfoRs.moveToInsertRow()	
	  $$$TRACE("After Info ResultSet")  
      do ..msprAffRs.moveToInsertRow() 
      $$$TRACE("After Insert Row move")
      //Set the parameters
      do ..setMsprInfoValues(pRequest.ldapTableValues.MSPRINFO)    
      $$$TRACE("After Setting values ")
      //Insert the row    
      do ..msprInfoRs.insertRow()
      //Clear the result set
      do ..msprInfoRs.close()
      //set the parameter for affliation table
      do ..setMsprAffiliationValues(pRequest.ldapTableValues.MSPRAFFLIATION)
      $$$TRACE("After Insert close 1")
      //Inser the affliation
      do ..msprAffRs.insertRow()
        $$$TRACE("After Insert close 2")
      //Close the result set
      do ..msprAffRs.close()        
      //Commit the connection
      $$$TRACE("After Insert close 3")

	   do ..createQueryStatement(pRequest)
       // Execute mspr query
       set ..msprInfoRs = ..msprInfoStmt.executeQuery()
       $$$TRACE("After query Execution1")       
	   do ..msprInfoRs.moveToInsertRow()	         
       $$$TRACE("After Insert Row move")
       //Set the parameters
       do ..setMsprInfoValues(pRequest.ldapTableValues.MSPRINFO)    
       $$$TRACE("After Setting value... ")
       //Insert the row    
       do ..msprInfoRs.insertRow()
       //Clear the result set
       do ..msprInfoRs.close()
       $$$TRACE("After Insert")
       set affiliationList= pRequest.ldapTableValues.MsprAffliationList
       $$$TRACE("MsprAffliation List count:"_affiliationList.Count())
       FOR i=1:1:affiliationList.Count(){
	       $$$TRACE("Inside affiation Loop-"_i)
	       set affobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRPRAFFLIATION).%New()
           set affobj = affiliationList.GetAt(i) 	                         
           //Execute the Mspr Provider Afflication query
           set ..msprAffRs = ..msprProviderAfflicationStmt.executeQuery()
           $$$TRACE("After query Execution")
           //Store affliation table
           do ..msprAffRs.moveToInsertRow() 
          //set the parameter for affliation table
           do ..setMsprAffiliationValues(affobj)
          $$$TRACE("After Insert close 1")
          //Inser the affliation
          do ..msprAffRs.insertRow()
          //Close the result set
          do ..msprAffRs.close()        
          //Commit the connection
          $$$TRACE("After Insert close 2")
       }
       set specialTyList= pRequest.ldapTableValues.MsprSpecialtyList
       $$$TRACE("specialTyList count:"_specialTyList.Count())
       FOR i=1:1:specialTyList.Count(){
	       $$$TRACE("Inside Specialty Loop-"_i)
	       set specialTyobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRSPECIALTY).%New()
           set specialTyobj = specialTyList.GetAt(i) 	                         
           //Execute the Mspr Provider Specialty query
           set ..msprSpecialTyRs = ..msprSpecialTystmt.executeQuery()
           $$$TRACE("After Speciality query Execution")
           //Store Specialty table
           do ..msprSpecialTyRs.moveToInsertRow() 
          //set the parameter for Specialty table
           do ..setMsprSpecialtyValues(specialTyobj)
          $$$TRACE("After Inser close 1")
          //Inser the specialties
          do ..msprSpecialTyRs.insertRow()
          //Close the result set
          do ..msprSpecialTyRs.close()        
          //Commit the connection
          $$$TRACE("After insert Specialty close 3")
       }

	   do ..createQueryStatement(pRequest)
       // Execute mspr query
       set ..msprInfoRs = ..msprInfoStmt.executeQuery()
       $$$TRACE("After query Execution1")       
	   do ..msprInfoRs.moveToInsertRow()	         
       $$$TRACE("After Insert Roew move")
       //Set the parameters
       do ..setMsprInfoValues(pRequest.ldapTableValues.MSPRINFO)    
       $$$TRACE("After Setting value, insert the row... ")
       //Insert the row    
       do ..msprInfoRs.insertRow()
       //Clear the result set
       do ..msprInfoRs.close()
       $$$TRACE("After Insert")
       set affiationList= pRequest.ldapTableValues.MsprAffliationList
       $$$TRACE("List count:"_affiationList.Count())
       FOR i=1:1:affiationList.Count(){
	       do ..createQueryStatement(pRequest)
	       $$$TRACE("Inside affiation Loop-"_i)
	       set affobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRPRAFFLIATION).%New()
           set affobj = affiationList.GetAt(i) 	                         
           //Execute the Mspr Provider Afflication query
           set ..msprAffRs = ..msprProviderAfflicationStmt.executeQuery()
           $$$TRACE("After query Execution")
           //Store affliation table
           do ..msprAffRs.moveToInsertRow() 
          //set the parameter for affliation table
           do ..setMsprAffiliationValues(affobj)
          $$$TRACE("After Inser close 1")
          //Inser the affliation
          do ..msprAffRs.insertRow()
          //Close the result set
          do ..msprAffRs.close()        
          //Commit the connection
          $$$TRACE("After Inser close 2")
       }
       set specialTyList= pRequest.ldapTableValues.MsprSpecialtyList
       $$$TRACE("specialTyList count11:"_specialTyList.Count())
       FOR j=1:1:specialTyList.Count(){
	       $$$TRACE("Inside specialty Loop1-"_j)
	       do ..createQueryStatement(pRequest)
	       $$$TRACE("Inside Loop>")
	       set specialTyobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRSPECIALTY).%New()
           set specialTyobj = specialTyList.GetAt(j) 	 
            $$$TRACE("Inside Loop111")                        
           //Execute the Mspr Provider Afflication query
           set ..msprSpecialTyRs = ..msprSpecialTystmt.executeQuery()
           $$$TRACE("After Speciality query Execution")
           //Store affliation table
           do ..msprSpecialTyRs.moveToInsertRow() 
          //set the parameter for affliation table
           do ..setMsprSpecialtyValues(specialTyobj)
          $$$TRACE("After Inser close 1")
          //Inser the specialties
          do ..msprSpecialTyRs.insertRow()
          //Close the result set
          do ..msprSpecialTyRs.close()        
          //Commit the connection
          $$$TRACE("After Specialty close 2")
       }

$$$TRACE("Start of Setting Affliation values")
$$$TRACE("TRANSACTION_SEQ_NUM: "_..tempId) 
do ..msprAffRs.updateInt("TRANSACTION_SEQ_NUM",..tempId)	
$$$TRACE("TRANSACTION_TIME: "_pRequest.TRANSACTIONTIME) 
do ..msprAffRs.updateString("TRANSACTION_TIME",pRequest.TRANSACTIONTIME)
